mapper.select:
SELECT 
FROM stock_watch_technical_analysis t

WHERE t.id = #{id}

SELECT 
FROM stock_watch_technical_analysis t

WHERE t.analysis_task_id = #{analysisTaskId}

SELECT  FROM stock_watch_technical_analysis t
JOIN stock_watch_analysis_observation_identity i
  ON i.canonical_task_id = t.analysis_task_id AND i.analysis_scope = 'TECHNICAL_RUNTIME'

WHERE t.symbol = #{symbol}
  AND t.market = #{market}
  AND t.analysis_date = #{analysisDate}
  AND t.run_slot = #{runSlot}
  AND COALESCE(t.period_type, 'DAY') = #{periodType}
  AND (t.period_key = #{periodKey} OR (t.period_key IS NULL AND #{periodType} = 'DAY'))
ORDER BY t.id DESC
LIMIT 1

SELECT  FROM stock_watch_technical_analysis t

WHERE t.symbol = #{symbol}
  AND t.market = #{market}
  AND t.analysis_date >= #{startDate}
  AND t.analysis_date <= #{endDate}
  AND COALESCE(t.period_type, 'DAY') = #{periodType}

ORDER BY t.analysis_date DESC, t.gmt_create DESC, t.id DESC

SELECT  FROM stock_watch_technical_analysis t

WHERE t.symbol = #{symbol}
  AND t.market = #{market}
  AND COALESCE(t.period_type, 'DAY') = #{periodType}



          AND t.period_key IN

              #{key}



          AND 1 = 0


ORDER BY t.analysis_date DESC, t.gmt_create DESC, t.id DESC

SELECT  FROM stock_watch_technical_analysis t

WHERE t.symbol = #{symbol}
  AND t.market = #{market}
  AND COALESCE(t.period_type, 'DAY') = #{periodType}

ORDER BY t.gmt_create DESC, t.id DESC
LIMIT #{limit}

SELECT  FROM stock_watch_technical_analysis t
JOIN stock_watch_analysis_observation_identity i
  ON i.canonical_task_id = t.analysis_task_id AND i.analysis_scope = 'TECHNICAL_RUNTIME'

WHERE t.symbol = #{symbol}
  AND t.market = #{market}
  AND t.status = 'SUCCESS'
  AND COALESCE(t.period_type, 'DAY') = #{periodType}
  AND t.gmt_create >= #{since}
ORDER BY t.gmt_create DESC, t.id DESC
LIMIT 1

SELECT  FROM stock_watch_technical_analysis t
JOIN stock_watch_analysis_observation_identity i
  ON i.canonical_task_id = t.analysis_task_id AND i.analysis_scope = 'TECHNICAL_RUNTIME'
JOIN stock_watch_analysis_task atask ON atask.id = t.analysis_task_id
WHERE t.session_id = #{sessionId}
  AND t.symbol = #{symbol}
  AND t.market = #{market}
  AND t.status = 'SUCCESS'
  AND COALESCE(t.period_type, 'DAY') = #{periodType}
  AND (
      t.analysis_date < #{maxAnalysisDate}
      OR (t.analysis_date = #{maxAnalysisDate} AND t.run_slot <= #{maxRunSlot})
  )
  AND t.analysis_task_id IS NOT NULL
  AND t.data_snapshot_json IS NOT NULL
  AND atask.request_digest IS NOT NULL
  AND atask.request_envelope_json IS NOT NULL
  AND atask.purpose = 'stock-analysis-response-v6'
ORDER BY t.analysis_date DESC, t.run_slot DESC, t.gmt_create DESC, t.id DESC
LIMIT 1

SELECT  FROM stock_watch_technical_analysis t

WHERE t.symbol = #{symbol}
  AND t.market = #{market}
  AND t.status = 'SUCCESS'
  AND t.analysis_date >= #{startDate}
  AND t.analysis_date <= #{endDate}
  AND COALESCE(t.period_type, 'DAY') = #{periodType}

ORDER BY t.analysis_date ASC, t.gmt_create ASC, t.id ASC
LIMIT #{limit}

SELECT FROM stock_watch_technical_analysis t
WHERE t.symbol = #{symbol} AND t.market = #{market} AND t.status = 'SUCCESS' AND t.analysis_date >= #{startDate} AND t.analysis_date <= #{endDate} AND COALESCE(t.period_type, 'DAY') = #{periodType}
AND t.id = ( SELECT t2.id FROM stock_watch_technical_analysis t2 LEFT JOIN stock_watch_analysis_observation_identity i2 ON i2.canonical_task_id = t2.analysis_task_id JOIN stock_watch_analysis_migration_state ms2 ON ms2.migration_key = 'stock-watch-v6' AND ms2.generation = 6 AND ms2.status = 'READY' WHERE t2.symbol = t.symbol AND t2.market = t.market AND t2.status = 'SUCCESS' AND t2.analysis_date = t.analysis_date AND COALESCE(t2.period_type, 'DAY') = COALESCE(t.period_type, 'DAY') AND (i2.analysis_scope = 'TECHNICAL_RUNTIME' OR (t2.analysis_task_id IS NULL AND t2.id <= ms2.legacy_analysis_cutoff_id)) ORDER BY t2.gmt_create DESC, t2.id DESC LIMIT 1 ) ORDER BY t.analysis_date DESC, t.gmt_create DESC, t.id DESC LIMIT #{limit}

SELECT  FROM stock_watch_technical_analysis t

WHERE t.symbol = #{symbol}
  AND t.market = #{market}
  AND t.status = 'SUCCESS'
  AND t.analysis_date >= #{startDate}
  AND t.analysis_date <= #{endDate}
  AND COALESCE(t.period_type, 'DAY') = #{periodType}

ORDER BY t.analysis_date DESC, t.run_slot DESC, t.gmt_create DESC, t.id DESC
LIMIT #{limit}

SELECT  FROM stock_watch_technical_analysis t
JOIN stock_watch_analysis_observation_identity i
  ON i.canonical_task_id = t.analysis_task_id AND i.analysis_scope = 'TECHNICAL_RUNTIME'

WHERE t.symbol = #{symbol}
  AND t.market = #{market}
  AND t.status = 'SUCCESS'
  AND t.gmt_create >= #{activeFrom}
ORDER BY t.gmt_create ASC, t.id ASC
LIMIT #{limit}
